 static string dir;static int checks;static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}static T F<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static void Near(double a,double b,double eps,string m){Check(Math.Abs(a-b)<=eps,m+": "+a+" / "+b);}static void Mouse(PreviewPanel p,string n,PointF pt){C(p,n,new MouseEventArgs(MouseButtons.Left,1,(int)Math.Round(pt.X),(int)Math.Round(pt.Y),0));if(n=="OnMouseMove")C(p,"FlushDragMove");}
 static LabelSettings Sample(){var s=LabelSettings.Default();s.Width=110;s.Height=90;s.BarX=48;s.BarY=35;s.BarWidth=45;s.Texts[0].X=12;s.Texts[0].Y=18;s.Texts[0].Width=30;s.Texts[0].Height=9;s.Texts[0].Text="Rotácia ABC 123";s.Texts[0].Size=12;s.Symbols.Add(new SymbolItem{X=12,Y=55,Width=15,Height=15*DepositArt.Aspect});return s;}
 static void Export(LabelSettings s,string name){Engine.Save(Path.Combine(dir,name+".ean.xml"),s);Engine.Svg(Path.Combine(dir,name+".svg"),s);Engine.Pdf(Path.Combine(dir,name+".pdf"),s);Engine.Docx(Path.Combine(dir,name+".docx"),s);Engine.Zpl(Path.Combine(dir,name+".zpl"),s);using(var b=Engine.Render(s))b.Save(Path.Combine(dir,name+".png"));using(var b=VectorArt.Raster(s,s.Dpi,true))b.Save(Path.Combine(dir,name+"-mono.png"));Check(File.ReadAllText(Path.Combine(dir,name+".svg")).Contains("transform=\"rotate("),"SVG transforms");Check(!File.ReadAllText(Path.Combine(dir,name+".pdf")).Contains("/Subtype /Image"),"PDF stays vector");using(var z=ZipFile.OpenRead(Path.Combine(dir,name+".docx"))){int count=0;foreach(var entry in z.Entries)if(entry.FullName.EndsWith(".svg")){using(var read=new StreamReader(entry.Open()))Check(read.ReadToEnd().Contains("rotate("),"Word SVG transform");count++;}Check(count==3,"Word independent elements");}var loaded=Engine.Load(Path.Combine(dir,name+".ean.xml"));Near(loaded.BarRotation,s.BarRotation,0,"code XML");Near(loaded.Texts[0].Rotation,s.Texts[0].Rotation,0,"text XML");var zp=ZplImport.Project(File.ReadAllText(Path.Combine(dir,name+".zpl")));Near(zp.BarRotation,s.BarRotation,0,"ZPL metadata rotation");}
 static void Pure(){foreach(double angle in new[]{0d,45,90,180,270}){var s=Sample();s.BarRotation=s.Texts[0].Rotation=s.Symbols[0].Rotation=angle;Export(s,"angle-"+angle);var e=ElementTransform.Get(s,0);var center=ElementTransform.Center(e);var corners=ElementTransform.Corners(e);foreach(var c in corners){var back=ElementTransform.Rotate(c,center,-angle);Check(back.X>=e.X-.001&&back.X<=e.X+e.Width+.001,"inverse X");}using(var scene=VectorArt.Build(s))foreach(var sh in scene.Shapes)Near(sh.Rotation,angle,0,"scene rotation all shapes");}var code=Sample();code.Kind=128;code.Ean="CODE128-TEST";code.BarRotation=90;Export(code,"code128-90");var overflow=Sample();overflow.Texts[0].X=-12;overflow.Texts[0].Rotation=45;overflow.BarX=80;overflow.BarRotation=37;overflow.Symbols[0].X=-7;overflow.Symbols[0].Rotation=270;Export(overflow,"overflow");Check(Engine.Warnings(overflow).Count>0,"overflow warning without block");
 foreach(double angle in new[]{-720d,-90,0,359.99,360,721})Check(ElementTransform.Normalize(angle)>=0&&ElementTransform.Normalize(angle)<360,"normalize");Near(ElementTransform.SnapAngle(37,true),30,0,"Shift snap");Near(ElementTransform.SnapAngle(38,true),45,0,"Shift next");Near(ElementTransform.SnapAngle(37.125,false),37.125,0,"smooth");Near(ElementTransform.SnapAngle(359,true),0,0,"snap wrap");
 var xml=File.ReadAllText(Path.Combine(dir,"angle-45.ean.xml"));xml=Regex.Replace(xml,@"<(?:BarRotation|Rotation)>.*?</(?:BarRotation|Rotation)>","");File.WriteAllText(Path.Combine(dir,"legacy.ean.xml"),xml);var old=Engine.Load(Path.Combine(dir,"legacy.ean.xml"));Near(old.BarRotation,0,0,"legacy barcode");Near(old.Texts[0].Rotation,0,0,"legacy text");Near(old.Symbols[0].Rotation,0,0,"legacy symbol");
 foreach(int kind in MoreBarcodes.Kinds){var s=Sample();s.Kind=kind;s.Ean=BarcodeCatalog.Sample(kind);if(kind==1002){s.Width=200;s.BarWidth=140;}s.BarRotation=37;using(var scene=VectorArt.Build(s)){Check(scene.Shapes.Count>0,"all formats rotate "+kind);}}
 }
 static void Ui(){using(var f=new MainForm(Path.Combine(dir,"prefs.xml"))){f.Icon=new Icon(Path.Combine(TestPaths.RepositoryRoot,"assets","app.ico"));f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Size=new Size(1440,960);f.Show();var p=F<PreviewPanel>(f,"preview");foreach(double zoom in new[]{0d,1,2})foreach(int index in new[]{0,-1,-3}){var s=Sample();s.BarRotation=s.Texts[0].Rotation=s.Symbols[0].Rotation=45;C(f,"Apply",s);p.ViewZoom=zoom;p.SelectElement(index);var original=p.Element(index).Copy();var other=p.Element(index==0?-1:0).Copy();var handle=p.RotationHandle();var center=p.ScreenPoint(ElementTransform.Center(original));var end=ElementTransform.Rotate(handle,center,37);var scene=p.Scene;Mouse(p,"OnMouseDown",handle);Mouse(p,"OnMouseMove",end);Check(p.IsDragging,"rotation active");Near(p.Element(index).Rotation,82,1,"mouse rotation");Check(object.ReferenceEquals(scene,p.Scene),"rotation reuses vector scene");C(p,"ProcessCmdKey",new Message(),Keys.Escape);Near(p.Element(index).Rotation,45,0,"Escape restores rotation");Near(p.Element(index).X,original.X,0,"rotation preserves X");
 handle=p.RotationHandle();end=ElementTransform.Rotate(handle,center,45);Mouse(p,"OnMouseDown",handle);Mouse(p,"OnMouseMove",end);Mouse(p,"OnMouseUp",end);Near(p.Element(index).Rotation,90,1,"release commits rotation");var after=p.Element(index);Near(after.Width,original.Width,.00001,"rotation preserves width");var neighbor=p.Element(other.Index);Near(neighbor.X,other.X,0,"other X unchanged");Near(neighbor.Y,other.Y,0,"other Y unchanged");Near(neighbor.Width,other.Width,0,"other width unchanged");Near(neighbor.Height,other.Height,0,"other height unchanged");Near(neighbor.Rotation,other.Rotation,0,"other rotation unchanged");
 var at=p.ScreenPoint(ElementTransform.Center(after));Mouse(p,"OnMouseDown",at);var moved=new PointF(at.X+19,at.Y+23);Mouse(p,"OnMouseMove",moved);Mouse(p,"OnMouseUp",moved);Near(p.Element(index).Rotation,after.Rotation,0,"move preserves angle");Check(p.Element(index).X!=after.X||p.Element(index).Y!=after.Y,"rotated object moves");
 p.SelectElement(index);var fixedCorner=p.Handles()[0];var resize=p.Handles()[4];var shift=ElementTransform.Vector(15,10,p.Element(index).Rotation);var target=new PointF(resize.X+shift.X,resize.Y+shift.Y);Mouse(p,"OnMouseDown",resize);Mouse(p,"OnMouseMove",target);Mouse(p,"OnMouseUp",target);var anchored=p.Handles()[0];Near(anchored.X,fixedCorner.X,1,"resize anchor X");Near(anchored.Y,fixedCorner.Y,1,"resize anchor Y");
 }
 foreach(double rotation in new[]{45d,90,137,270})foreach(int index in new[]{0,-1,-3})for(int h=0;h<8;h++){var model=Sample();model.BarRotation=model.Texts[0].Rotation=model.Symbols[0].Rotation=rotation;C(f,"Apply",model);p.ViewZoom=0;p.SelectElement(index);var handles=p.Handles();var anchor=handles[(h+4)%8];var shift=ElementTransform.Vector(h==0||h==6||h==7?-12:12,h<=2?-10:10,rotation);var target=new PointF(handles[h].X+shift.X,handles[h].Y+shift.Y);Mouse(p,"OnMouseDown",handles[h]);Mouse(p,"OnMouseMove",target);Mouse(p,"OnMouseUp",target);Near(p.Element(index).Rotation,rotation,0,"resize angle unchanged");var final=p.Handles()[(h+4)%8];Near(final.X,anchor.X,1,"all rotated handles anchor X");Near(final.Y,anchor.Y,1,"all rotated handles anchor Y");}
 var sample=Sample();sample.Texts[0].Rotation=45;C(f,"Apply",sample);p.ViewZoom=0;p.SelectElement(0);F<NumericUpDown>(f,"textRotation").Value=123.45m;Near(((LabelSettings)C(f,"Read")).Texts[0].Rotation,123.45,.00001,"manual decimal angle");p.Focus();C(f,"ProcessCmdKey",new Message(),Keys.Control|Keys.OemCloseBrackets);Near(p.Element(0).Rotation,213.45,.00001,"Ctrl right");C(f,"ProcessCmdKey",new Message(),Keys.Control|Keys.OemOpenBrackets);Near(p.Element(0).Rotation,123.45,.00001,"Ctrl left");var menu=F<ContextMenuStrip>(f,"rotationMenu");((ToolStripMenuItem)menu.Items[1]).PerformClick();Near(p.Element(0).Rotation,0,0,"context reset");C(f,"SetSelectedRotation",37d);var clipboard=(string)C(f,"CopyElementData");C(f,"PasteElementData",clipboard);Near(p.Element(p.SelectedIndex).Rotation,37,0,"copied text rotation");
 C(f,"Apply",sample);p.SelectElement(0);foreach(string language in Loc.Codes){Loc.Language=language;C(f,"Localize");Check(F<NumericUpDown>(f,"textRotation").AccessibleName==Loc.T("Rotácia"),"angle accessibility localized");Check(F<ContextMenuStrip>(f,"rotationMenu").Items[0].Text==Loc.T("Rotácia"),"context localized");}Loc.Language="sk";C(f,"Localize");foreach(Control child in F<TableLayoutPanel>(f,"studio").Controls)if(child is TableLayoutPanel)foreach(Control label in child.Controls)if(label.Name=="AppVersion")Check(label.Visible&&label.Text=="Pre-release"&&label.Width>30,"visible version footer");using(var bmp=new Bitmap(p.Width,p.Height))p.DrawToBitmap(bmp,p.ClientRectangle);using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(dir,"editor-rotation.png"));}C(f,"Apply",LabelSettings.Default());f.Close();}
 // Standalone preview checks selection and double-click without opening a modal text editor.
 using(var host=new Form{ClientSize=new Size(900,700),StartPosition=FormStartPosition.Manual,Location=new Point(-20000,-20000)})using(var p=new PreviewPanel{Dock=DockStyle.Fill,Compact=true}){var s=Sample();s.Texts[0].Rotation=90;p.Settings=s;p.Scene=VectorArt.Build(s);p.Image=new Bitmap(1,1);host.Controls.Add(p);host.Show();p.SelectElement(-1);var e=ElementTransform.Get(s,0);var test=ElementTransform.Rotate(new PointF((float)(e.X+2),(float)(e.Y+e.Height/2)),ElementTransform.Center(e),90);var screen=p.ScreenPoint(test);Check(!ElementTransform.LocalBounds(e).Contains(test),"test outside original unrotated box");Mouse(p,"OnMouseDown",screen);Mouse(p,"OnMouseUp",screen);Check(p.SelectedIndex==0,"hit rotated object outside old box");int edited=-2;p.TextEditRequested+=delegate(int index){edited=index;};Mouse(p,"OnMouseDoubleClick",screen);Check(edited==0,"double-click rotated text");host.Close();}
 }
 [STAThread]static void Main(string[] a){dir=a[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Pure();Ui();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+checks+" rotation assertions: matrix geometry, vector export cases, all barcode types, decimal/Shift/wrap, legacy XML, rotated hit/double-click, mouse rotation/move/resize at three zooms, Escape, cached rendering, isolation, shortcuts, context reset, copy.");}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
